('8b151bb1-a8ff-42d3-8358-5ec78e096855', '21feff02-016d-46e2-bb9d-c27495133b1b', '28. óra: Mit tanultunk a törtekről? Ismétlés', 'Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "17e07e3f-5c76-42f1-9842-7238839750be", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "16a0f9ee-e7fb-424b-a7e1-542ea8b70349", "text": "Számláló", "isCorrect": true}, {"id": "f086becb-2017-4735-b9e0-55d6f9bb20ea", "text": "Nevező", "isCorrect": false}, {"id": "734ae0d3-1789-4982-a6f5-1985581bd413", "text": "Törtvonal", "isCorrect": false}, {"id": "e6eeaa19-1c0c-4cfa-a406-aec41bafc7aa", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "fd84f8fd-2a39-4a23-b27b-d358630cfcc2", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "b871e3b6-c9fa-48e6-b86c-eddf814002ed", "text": "Nevező", "isCorrect": true}, {"id": "3d55f34d-e62b-4874-a875-dffdffbe2f49", "text": "Számláló", "isCorrect": false}, {"id": "fd7a4265-dcb2-46fa-8b34-3ee17ee8b765", "text": "Osztó", "isCorrect": false}, {"id": "2ef0504c-d976-4c5c-b833-424b418b44d0", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "1c624f05-f1f1-4fb5-bc8a-b0bcd170f33b", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "f2e396d0-a4d3-468a-95ee-9d08998776fe", "text": "6/8", "isCorrect": true}, {"id": "2058f5eb-a9de-40aa-af19-ca5d37979115", "text": "5/6", "isCorrect": false}, {"id": "07f36a08-25c5-4aae-85d9-4c49fb4674ea", "text": "3/8", "isCorrect": false}, {"id": "d61f4612-846d-4742-9142-7e1876be5393", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "5caab7d5-b242-4615-b5da-58474626f8f8", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "17dba91a-104c-4e9e-a950-aeaf0c9d857a", "text": "3/5", "isCorrect": true}, {"id": "f58c03a1-397d-440f-9d17-021fe4bba550", "text": "3/10", "isCorrect": false}, {"id": "425e28d1-2482-4159-be2b-bee3ea4de04d", "text": "6/5", "isCorrect": false}, {"id": "6ca6f530-8220-4f4a-8f68-7df0ae4f25fe", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "c030c111-b09c-4af9-bd32-eec9f061653d", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "f02e16e0-687b-4d38-994a-c18bac9d290b", "text": "Igaz", "isCorrect": true}, {"id": "b701f02d-10e1-425e-a34f-5686f630fa0a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9f3ca87e-2149-4ccf-865d-4f7c42cd2143", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "58aabc13-aa1a-4a91-b755-9698e7b47eca", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "bdbd394f-f857-4744-8647-345ec5582d3e", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "2568409b-80b8-4488-ac23-d2c69d51c257", "text": "2/6", "isCorrect": false}, {"id": "0347df96-5cc1-469d-b330-d1f70fc65233", "text": "2/4", "isCorrect": false}, {"id": "677298a6-df3b-44da-aaa2-8d7d92123e15", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('93e27534-3fc1-4980-89bb-aba0cff1d92e', '21feff02-016d-46e2-bb9d-c27495133b1b', '29. óra: Mit tanultunk a törtekről? Ismétlés II.', 'Összeadás és kivonás azonos és különböző nevezőjű törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "ec3e4839-d158-4711-b9a1-987fb525bff9", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "5475f3f2-b6fb-4f78-b4bc-09853c4e48a8", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "1712ffa1-789d-49c0-90f6-4ddfeb89a126", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "9c4171ef-ebea-42b8-9610-548a8b60064d", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "f678583b-e772-4db7-b1d0-ebc2fb624957", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "5ab2b257-cd54-43aa-b913-d92af67546ea", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "b3de83fa-ec1b-4cb6-8d91-a519c3eaea9b", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "a76589e5-f61c-4648-b92f-1332a59430d3", "text": "2/9", "isCorrect": false}, {"id": "101b50aa-adde-4fe1-ac2d-80b05ca6d71c", "text": "1/9", "isCorrect": false}, {"id": "198761bf-04c4-4425-8a5e-0fcdf166cfb8", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "1e2599dc-d5f3-4d3d-91ee-89b0d0691419", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "df01c530-83b3-4679-a072-820f3910efdd", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "565ef588-39cb-41c9-87e0-5b2434fbbdde", "text": "2/0", "isCorrect": false}, {"id": "7667bbf7-f7a5-44fa-a02f-c223a0cb65ab", "text": "8/8", "isCorrect": false}, {"id": "cd87a833-5cee-44d8-9371-ae1a58cf7644", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "bce3c02d-a3d3-47bf-9e69-9d92ecd696bd", "text": "Az 1/2 és 2/4 egyenlő értékű törtek.", "type": "true-false", "options": [{"id": "430e7bae-4d25-437f-a51a-0a66df9602b4", "text": "Igaz", "isCorrect": true}, {"id": "72b769c5-ec7d-438a-922b-7ce322ab571c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eac95010-c72f-4bae-a6e1-9e89017ed9ec", "text": "Hány nyolcad van 3/4-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "7fdc5488-e0a4-4ac2-9118-0b0154fc297f", "text": "Mennyi 1 egészből kivonva 2/5-öt?", "type": "multiple-choice", "options": [{"id": "aec5ef6c-8c20-4aa6-b8d3-1067e861da43", "text": "3/5", "isCorrect": true}, {"id": "9f3b6e75-d582-4d13-8123-b007f1032a43", "text": "1/5", "isCorrect": false}, {"id": "4cea454c-1a90-40c2-95ee-1e1d1e3c8fcf", "text": "2/5", "isCorrect": false}, {"id": "33d71fae-1ec1-43ce-bbaf-cfee1c6f025c", "text": "5/5", "isCorrect": false}], "timeLimit": 15}, {"id": "052d6e42-d349-4ba7-ad49-81bffff415f2", "text": "A törtvonal osztás műveletet jelent.", "type": "true-false", "options": [{"id": "b991770c-9ba4-449d-b3d3-851a54451ea3", "text": "Igaz", "isCorrect": true}, {"id": "4a2a4c77-2e60-409e-a3bd-1e357231e23d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('d0d74ffe-851d-4cd3-8024-3f1c5536a91b', '21feff02-016d-46e2-bb9d-c27495133b1b', '30. óra: Szorzás törttel, a reciprok', 'Tört szorzása törttel, reciprok fogalma.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "a7761398-2493-44e8-aba0-7f14d7f77bea", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "79ed33de-7135-4a24-b203-9a8d6058ef00", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "30f3cfbf-f9cf-4fe3-83e2-33bf340ff7d2", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "d1010365-5fd6-4df8-ac74-cb37b73243cc", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "bc0ec950-fbcc-418c-9456-cdc7779150c1", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "70af536b-4160-488c-8e76-64453c73b811", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "28bbcf34-3188-498a-85df-610d58a24542", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "9f61fa00-3587-4256-bde2-cc74345db996", "text": "5/8", "isCorrect": false}, {"id": "3da39d4a-f678-4529-aaeb-785096e062ab", "text": "6/8", "isCorrect": false}, {"id": "8ddb4ea3-7407-4b31-a90f-0e7a1f44a2ad", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "dd07e22c-9d6c-4b93-b12a-61b35b91dce6", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "09d6886a-b512-4445-a676-19ed2000e1c9", "text": "4/3", "isCorrect": true}, {"id": "aad3dab3-865c-4065-9750-b51f1f529833", "text": "-3/4", "isCorrect": false}, {"id": "4f4779e0-7faf-4578-b16a-288294758e07", "text": "1/4", "isCorrect": false}, {"id": "e72e3ecc-b5f7-4e99-9cbd-52646e365485", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "43241f66-2f6b-4873-84f2-8ae4b2e9d8a5", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "05cfd035-0140-46e7-96dd-223c1889da68", "text": "Igaz", "isCorrect": true}, {"id": "15f79932-c00a-42a3-854b-428a4d1ef012", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "62b93738-5b19-46bb-ac75-8217e416358f", "text": "Mi a 5 egész reciproka?", "type": "multiple-choice", "options": [{"id": "282ae20c-30dc-4878-aeb1-bc7f6deb3fd4", "text": "1/5", "isCorrect": true}, {"id": "7cb08733-2cc9-401d-ae84-407458474bea", "text": "-5", "isCorrect": false}, {"id": "bfad959b-ae7f-46ad-9ffb-559bf5d941b9", "text": "5/1", "isCorrect": false}, {"id": "6124fb94-3300-4135-aedc-b03822f05172", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "db0362c0-0d89-4e3c-ad4e-d20899c1ec01", "text": "A 0-nak nincs reciproka.", "type": "true-false", "options": [{"id": "794c7881-1a45-4c07-9e76-56de466e7a49", "text": "Igaz", "isCorrect": true}, {"id": "65d1f8ba-a036-4eb7-9c41-3c822394df3f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "313f1fce-bcfc-45c2-a9b8-5596a71a73e8", "text": "Mennyi 1/2 * 1/3?", "type": "multiple-choice", "options": [{"id": "e0e75e28-f0a8-40e5-b173-05290b7e360f", "text": "1/6", "isCorrect": true}, {"id": "ee8c4953-486f-403a-83e4-eb3c8f8621bd", "text": "2/5", "isCorrect": false}, {"id": "e494784a-1ade-431f-a49d-be31d2e39c78", "text": "1/5", "isCorrect": false}, {"id": "4d8da838-7755-457a-9b60-171acc2e1979", "text": "2/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('be0ed83d-b65c-4400-be11-1af5e80d8452', '21feff02-016d-46e2-bb9d-c27495133b1b', '31. óra: A törtek szorzását alkalmazó feladatok megoldása', 'Törtrész kiszámítása és szöveges feladatok megoldása szorzással.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "0a539599-7723-4805-9319-8f18c0743cd2", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "6dd2eb7c-4b78-4674-b8d4-9de9e901769d", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "d042f46d-8303-4ae1-81f6-bb8e4f39a523", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "f83fed45-9fe7-49b1-9360-7468a2608dc3", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "b9b17cc9-f76f-4709-96f9-159429ac0210", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "b8a17fe0-ac55-45f8-ac80-e71d6067ef34", "text": "Igaz", "isCorrect": true}, {"id": "569ea74e-e6aa-4d25-ab7a-4ed55bd64a3b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fa0ff6ea-d444-4bcb-a14c-6c8516c7e263", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "351f42c7-9d4b-4e06-96d8-181515f23217", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()),
('f6c9312f-e615-4db4-a884-dde735c419ec', '21feff02-016d-46e2-bb9d-c27495133b1b', '32. óra: Osztás törttel', 'Törttel való osztás szabálya: szorzás a reciprokával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "3cab197f-b86e-44e5-b972-6783f40417fc", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "3729c461-1f5d-4535-926f-70954a18a98e", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "1a94b93b-020f-4154-8faa-20bbce65664d", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "0edceebb-8091-4826-a888-c1eedec0ec32", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "a95ec63a-682c-4374-b224-045d95fcc3f7", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "b5d523df-b5e8-4486-a19b-599e53604534", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "492f9ac1-1a67-486f-9688-c3cecc9e84fb", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "d0489425-5bab-484a-808a-eb84ba1052d3", "text": "8/15", "isCorrect": false}, {"id": "f9a5e253-476e-466a-8bfe-a10eff1c602a", "text": "6/8", "isCorrect": false}, {"id": "60524977-4175-4a54-a0e7-027493868c08", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "a8e2af09-978e-4ce7-9768-30b62c8c99f6", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "3c78cd19-d859-4f01-a814-a60b9d6884b8", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "f73b6896-28ce-4c30-a5a9-5e4805ececea", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "e92570da-1f6a-42e7-b36f-d0bf5549eab2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "63e2c141-191b-4902-8c12-71bfada5ad50", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "23b48ea0-3811-4f74-b0a4-d7e3b53564ca", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "83cf315c-cf8d-4381-8bed-36ccd350b5f2", "text": "Igaz", "isCorrect": true}, {"id": "58036912-adc9-49c5-beb1-5d0e4ff89583", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3bb010b0-1b4f-4aae-a811-99b43d7a2f4c", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW()),
('4ed48a8e-3f8a-4382-8fd6-99415a2af14b', '21feff02-016d-46e2-bb9d-c27495133b1b', '33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával', 'Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "efec8b56-6c51-4a2b-a455-58925bc2696f", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "1c6b8491-4db2-40c7-9be4-13f7cf9abee2", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "2cabf265-1f46-4567-8566-7aa222d85e2a", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "e6f61c7a-8252-431d-9e22-9a419c350a73", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "984de080-704e-4ff1-b646-d2acee8110ac", "text": "Igaz", "isCorrect": true}, {"id": "9ac358c7-ad3f-4660-8661-aab1e1449deb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "86d3321d-ede6-456a-a3e0-552772d196ff", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "7c4e0138-6003-4dab-97f0-182531e44397", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "559aa758-576e-4631-b14f-31a62bfec1e2", "text": "Igaz", "isCorrect": true}, {"id": "3c753c75-3b38-42d9-950e-f2509c9725d2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "344a04be-aac7-432d-a37e-be0ed8cbb62e", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()),
('df2ecd84-5916-46c3-ad78-80b2d09ed363', '21feff02-016d-46e2-bb9d-c27495133b1b', '34. óra: Gyakorlóóra', 'A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "6bbbee50-936d-4364-a6dd-e6d063f95823", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "bb629e1f-dc19-4ae3-9641-034257a69cc3", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "5287de7a-c5c5-4b2a-833a-bb67c774c7ba", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "2fb9df4b-4432-4270-a758-f8ce56a56104", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "75ca39ab-929d-4c7a-9b65-a6b5a24fce94", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "4b5396ec-da97-4e3c-b5d9-dc597a17259f", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "2bb1d18c-907c-4510-b8b9-7b5c9fb59c2d", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "3b18fef6-da3d-43f7-a6a2-3925c31a6cba", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "f734afd5-91a3-40a2-a25a-b59629bb069b", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "30b28613-7728-44c7-a0a6-922df109c394", "text": "Igaz", "isCorrect": true}, {"id": "16943053-892b-48df-bd44-eafcb25f4d62", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d654c8ac-8791-4925-bab6-cb6cd4e6b49c", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "08ee93df-5036-4154-a976-c838748a109f", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "523fc1da-0999-4c30-b381-977a5f07d37d", "text": "1/5", "isCorrect": true}, {"id": "5684c3d4-eb06-4d5b-ae9a